def run_site_write_isolation_readiness_smoke() -> None:
    script_path = TOOLS_DIR / "check_site_write_isolation_readiness.py"
    if not script_path.exists():
        raise AssertionError("check_site_write_isolation_readiness.py does not exist.")

    result = subprocess.run(
        [
            sys.executable,
            str(script_path),
        ],
        cwd=ROOT_DIR,
        capture_output=True,
        text=True,
        check=True,
    )
    required_fragments = (
        "PASS site write isolation readiness check passed.",
        "status: ENFORCED",
        "/api/progress",
        "/api/unit-extra",
        "/api/vendor-contact",
        "/api/vendor-work-entry",
    )
    for fragment in required_fragments:
        if fragment not in result.stdout:
            raise AssertionError(f"check_site_write_isolation_readiness.py output missing: {fragment}")

    self_test = subprocess.run(
        [sys.executable, str(script_path), "--self-test"],
        cwd=ROOT_DIR,
        capture_output=True,
        text=True,
        check=False,
    )
    markers = (
        "PASS unit extra readiness checker negative controls passed.",
        "PASS vendor contact readiness checker negative controls passed.",
    )
    if self_test.returncode != 0:
        raise AssertionError(f"unit-extra readiness checker self-test failed: {self_test.stderr or self_test.stdout}")
    if self_test.stderr:
        raise AssertionError(f"unit-extra readiness checker self-test stderr was not empty: {self_test.stderr}")
    for marker in markers:
        if self_test.stdout.count(marker) != 1:
            raise AssertionError(f"readiness checker self-test marker count must be exactly one: {marker}")


