def fetch_vendor_work_entry_snapshot(entry_id: int) -> dict[str, object]:
    row = conn.execute(
        '''
        SELECT
            id,
            vendor_name,
            business_date,
            planned_at,
            planned_headcount,
            actual_headcount,
            work_content,
            pre_entry_requirement,
            work_headcount,
            entry_order
        FROM vendor_work_entries
        WHERE id = ?
        ''',
        (int(entry_id),),
    ).fetchone()
    if row is None:
        raise SystemExit(f"vendor work entry {entry_id} should exist")
    return dict(row)


