        "m=importlib.util.module_from_spec(s); s.loader.exec_module(m)\n"
        "m._sys.version_info=(3,13,0)\n"
        f"raise SystemExit(m._main(['--db',{str(exact_db)!r},'--run-id',{run_id!r},"
